import { Adapter, WhereClause } from "@superfunctions/db";
import { NonProductionBackendError } from "../core/errors.js";
import { secureRandomUUID } from "../utils/random.js";
import { cosineSimilarity, Document, Embeddings, matchesRetrievalFilter, RetrievalOptions, VectorStore } from "./base.js";

export interface DocumentRecord {
  id: string;
  content: string;
  embedding: number[];
  metadata: Record<string, unknown>;
  namespace: string;
  createdAt: number;
  score?: number;
}

export interface DbVectorStoreOptions {
  namespace?: string;
  mode?: "reference" | "production";
  pageSize?: number;
  maxScan?: number;
  indexedSearch?: (payload: {
    query: string;
    k: number;
    filter?: Record<string, unknown>;
    namespace: string;
    queryEmbedding: number[];
  }) => Promise<DocumentRecord[]>;
}

/**
 * Reference DB vector store. This fallback is intentionally non-production unless an indexed search callback is supplied.
 */
export class DbVectorStore extends VectorStore {
  readonly backendType: "reference" | "production";
  private readonly tableName = "langfn_documents";
  private readonly namespace: string;
  private readonly pageSize: number;
  private readonly maxScan: number;
  private readonly indexedSearch?: DbVectorStoreOptions["indexedSearch"];

  constructor(
    private readonly db: Adapter,
    private readonly embeddings: Embeddings,
    options: DbVectorStoreOptions = {}
  ) {
    super();
    this.namespace = options.namespace ?? "default";
    this.backendType = options.mode ?? "reference";
    this.pageSize = Math.max(1, options.pageSize ?? 64);
    this.maxScan = Math.max(this.pageSize, options.maxScan ?? 512);
    this.indexedSearch = options.indexedSearch;
  }

  async addDocuments(documents: Document[]): Promise<void> {
    const texts = documents.map((document) => document.content);
    const vectors = await this.embeddings.embedDocuments(texts);
    const records: DocumentRecord[] = documents.map((document, index) => ({
      id: `doc_${secureRandomUUID()}`,
      content: document.content,
      embedding: vectors[index]!,
      metadata: { ...document.metadata },
      namespace: this.namespace,
      createdAt: Date.now()
    }));
    await this.db.createMany({
      model: this.tableName,
      data: records
    });
  }

  async search(query: string, options: RetrievalOptions = {}): Promise<Document[]> {
    const k = options.k ?? 4;
    const queryEmbedding = await this.embeddings.embedQuery(query);
    const records = this.indexedSearch
      ? await this.indexedSearch({
          query,
          k,
          filter: options.filter,
          namespace: this.namespace,
          queryEmbedding
        })
      : await this.referenceSearch(queryEmbedding, options, k);

    return records
      .slice(0, k)
      .map((record) => ({
        content: record.content,
        metadata: { ...record.metadata },
        score: record.score
      }));
  }

  private async referenceSearch(
    queryEmbedding: number[],
    options: RetrievalOptions,
    k: number
  ): Promise<DocumentRecord[]> {
    if (this.backendType === "production") {
      throw new NonProductionBackendError("Production retrieval requires adapter-native indexed search or memoryfn", {
        metadata: { backend: "db-vector-store" }
      });
    }

    const where: WhereClause[] = [{ field: "namespace", operator: "eq", value: this.namespace }];
    const scored: DocumentRecord[] = [];
    let offset = 0;

    while (offset < this.maxScan) {
      const limit = Math.min(this.pageSize, this.maxScan - offset);
      const records = await this.db.findMany<DocumentRecord>({
        model: this.tableName,
        where,
        limit,
        offset
      });
      if (!records.length) {
        break;
      }

      records.forEach((record, index) => {
        if (!matchesRetrievalFilter(record.metadata ?? {}, options.filter)) {
          return;
        }
        scored.push({
          ...record,
          score: cosineSimilarity(queryEmbedding, record.embedding),
          createdAt: record.createdAt ?? offset + index
        });
      });

      offset += records.length;
      if (records.length < limit) {
        break;
      }
    }

    return scored
      .sort((left, right) => (right.score ?? 0) - (left.score ?? 0) || left.createdAt - right.createdAt)
      .slice(0, Math.max(k, 1));
  }
}
import { AgentMaxIterationsError, InternalError, ValidationError } from "../core/errors.js";

export interface CoordinatedAgent {
  run(task: string): Promise<string | { output: string }> | string | { output: string };
}

export interface MultiAgentResult {
  decisions: string[];
  outputs: string[];
  output: string;
}

export interface MultiAgentCoordinatorOptions {
  agents: Record<string, CoordinatedAgent>;
  coordinator: (task: string, context: { decisions: string[]; outputs: string[] }) => Promise<string> | string;
  max_iterations?: number;
}

export class MultiAgentCoordinator {
  constructor(private readonly options: MultiAgentCoordinatorOptions) {}

  async run(task: string): Promise<MultiAgentResult> {
    const decisions: string[] = [];
    const outputs: string[] = [];
    let currentTask = task;
    const maxIterations = this.options.max_iterations ?? 5;

    for (let iteration = 0; iteration < maxIterations; iteration += 1) {
      let decision: string;
      try {
        decision = await this.options.coordinator(currentTask, {
          decisions: [...decisions],
          outputs: [...outputs]
        });
      } catch (error) {
        throw new InternalError("Coordinator failed to select an agent", { cause: error });
      }

      if (decision === "__end__") {
        return {
          decisions,
          outputs,
          output: outputs[outputs.length - 1] ?? ""
        };
      }

      const agent = this.options.agents[decision];
      if (!agent) {
        throw new ValidationError(`Unknown agent: ${decision}`, { metadata: { agent: decision } });
      }

      decisions.push(decision);
      outputs.push(await normalizeAgentOutput(agent.run(currentTask)));
      currentTask = outputs[outputs.length - 1] ?? currentTask;
    }

    throw new AgentMaxIterationsError("Coordinator exceeded max iterations", {
      metadata: { max_iterations: maxIterations }
    });
  }
}

async function normalizeAgentOutput(
  value: Promise<string | { output: string }> | string | { output: string }
): Promise<string> {
  const resolved = await value;
  return typeof resolved === "string" ? resolved : resolved.output;
}
import { AbortError, LangFnError, RateLimitError } from "../core/errors.js";

export interface RetryConfig {
  signal?: AbortSignal;
  maxAttempts?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
  retryOnCodes?: readonly string[];
}

function shouldRetry(error: unknown, retryOnCodes: readonly string[]): boolean {
  return error instanceof LangFnError && retryOnCodes.includes(error.code);
}

export async function retryAsync<T>(
  fn: () => Promise<T>,
  config: RetryConfig = {}
): Promise<T> {
  const maxAttempts = config.maxAttempts ?? 3;
  const baseDelayMs = config.baseDelayMs ?? 250;
  const maxDelayMs = config.maxDelayMs ?? 5_000;
  const retryOnCodes = config.retryOnCodes ?? ["PROVIDER_RATE_LIMIT", "PROVIDER_TIMEOUT"];

  for (let attempt = 1; ; attempt += 1) {
    if (config.signal?.aborted) throw new AbortError();
    try {
      return await fn();
    } catch (error) {
      if (attempt >= maxAttempts || !shouldRetry(error, retryOnCodes)) {
        throw error;
      }

      let delay = Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1));
      delay = delay * (0.8 + Math.random() * 0.4);
      if (error instanceof RateLimitError && error.retryAfter !== undefined) {
        delay = Math.max(delay, error.retryAfter * 1_000);
      }
      await new Promise<void>((resolve, reject) => {
        const signal = config.signal;
        const abort = () => { clearTimeout(timer); signal?.removeEventListener("abort", abort); reject(new AbortError()); };
        const timer = setTimeout(() => { signal?.removeEventListener("abort", abort); resolve(); }, delay);
        signal?.addEventListener("abort", abort, { once: true });
        if (signal?.aborted) abort();
      });
    }
  }
}
import { Memory, MemoryRelationship } from '../core/types';

export interface MemoryScope { tenantId: string; containerTags: string[] }
export interface MemoryUpdate extends MemoryScope {
  id: string;
  expectedRevision: number;
  changes: Pick<Memory, 'content' | 'embedding'> & Partial<Pick<Memory, 'metadata' | 'isLatest'>>;
}
export interface MemoryDelete extends MemoryScope { id: string; expectedRevision?: number }
export interface StorageAdapter {
  /** Fixed vector dimension, shared across bundled entrypoints. */
  readonly embeddingDimensions?: number;
  close?(): Promise<void>;
  /** Commit all callback writes together, or leave storage unchanged on failure. */
  transaction?<T>(operation: (storage: StorageAdapter) => Promise<T>): Promise<T>;
  insertMemories(memories: Partial<Memory>[]): Promise<Memory[]>;
  insertRelationships(relationships: Partial<MemoryRelationship>[]): Promise<MemoryRelationship[]>;
  searchVectors(params: {
    tenantId?: string;
    embedding: number[];
    containerTags: string[];
    filters?: Record<string, any>;
    topK: number;
    threshold?: number;
  }): Promise<Memory[]>;
  getMemory(scope: MemoryScope & { id: string }): Promise<Memory | null>;
  updateMemory(input: MemoryUpdate): Promise<Memory>;
  deleteMemory(input: MemoryDelete): Promise<void>;
}

export function requireScope(tenantId: string | undefined, tags: string[]): asserts tenantId is string {
  if (!tenantId?.trim() || !Array.isArray(tags) || tags.some(tag => typeof tag !== 'string' || !tag.trim())) {
    throw new Error('MEMORY_SCOPE_REQUIRED');
  }
}
import {
  BadRequestError,
  ForbiddenError,
  InternalServerError,
  NotFoundError,
  RouterError,
  UnauthorizedError,
} from "@superfunctions/http";
import {
  SecFnError,
  SecFnForbiddenError,
  SecFnNotFoundError,
  SecFnUnauthorizedError,
  SecFnValidationError,
} from "@secfn/core";

export function ok(data: unknown, init?: ResponseInit): Response {
  return Response.json({ ok: true, data }, init);
}

export function emptyOk(init?: ResponseInit): Response {
  return Response.json({ ok: true, data: null }, init);
}

export function errorResponse(error: unknown): Response {
  const routerError = toRouterError(error);
  return Response.json(
    {
      ok: false,
      error: {
        code: routerError.code ?? "SECFN_INTERNAL",
        message: routerError.message,
      },
    },
    { status: routerError.statusCode },
  );
}

export async function readJson<T>(request: Request): Promise<T> {
  try {
    return await request.json() as T;
  } catch {
    throw new BadRequestError("Invalid JSON", "SECFN_BAD_JSON");
  }
}

function toRouterError(error: unknown): RouterError {
  if (error instanceof RouterError) return error;
  if (error instanceof SecFnUnauthorizedError) return new UnauthorizedError(error.message, error.code);
  if (error instanceof SecFnForbiddenError) return new ForbiddenError(error.message, error.code);
  if (error instanceof SecFnNotFoundError) return new NotFoundError(error.message, error.code);
  if (error instanceof SecFnValidationError) return new BadRequestError(error.message, error.code);
  if (error instanceof SecFnError) return new BadRequestError(error.message, error.code);
  return new InternalServerError("Internal Server Error", "SECFN_INTERNAL");
}
