export async function raiseForStatus(provider: string, response: Response): Promise<void> {
  if (response.ok) return;

  const retryAfter = parseRetryAfter(response.headers.get("retry-after"));
  const text = await response.text();
  let body: unknown;
  try {
    body = text ? JSON.parse(text) : {};
  } catch {
    body = text;
  }

  if (response.status === 401) {
    throw new ProviderAuthError(undefined, { provider, metadata: { status: response.status, body } });
  }
  if (response.status === 429) {
    throw new RateLimitError(undefined, {
      provider,
      retryAfter,
      metadata: { status: response.status, body }
    });
  }
  if (response.status === 400) {
    const error = typeof body === "object" && body ? (body as Record<string, any>).error ?? {} : {};
    const message = String(error.message ?? "");
    const code = String(error.code ?? error.type ?? "");
    if (
      code === "context_length_exceeded" ||
      (code === "invalid_request_error" && message.toLowerCase().includes("maximum context length"))
    ) {
      throw new ContextLengthError(undefined, { provider, metadata: { status: response.status, body } });
    }
  }

  throw new ProviderError(`OpenAI request failed (${response.status})`, {
    provider,
    metadata: { status: response.status, body }
  });
}

function parseRetryAfter(value: string | null): number | undefined {
  const normalized = value?.trim();
  if (!normalized) return undefined;
  const seconds = Number(normalized);
  return Number.isFinite(seconds) && seconds >= 0 ? seconds : undefined;
}
import { AbortError, LangFnError, RateLimitError } from "../core/errors.js";

export interface RetryConfig {
  signal?: AbortSignal;
  maxAttempts?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
  retryOnCodes?: readonly string[];
}

function shouldRetry(error: unknown, retryOnCodes: readonly string[]): boolean {
  return error instanceof LangFnError && retryOnCodes.includes(error.code);
}

export async function retryAsync<T>(
  fn: () => Promise<T>,
  config: RetryConfig = {}
): Promise<T> {
  const maxAttempts = config.maxAttempts ?? 3;
  const baseDelayMs = config.baseDelayMs ?? 250;
  const maxDelayMs = config.maxDelayMs ?? 5_000;
  const retryOnCodes = config.retryOnCodes ?? ["PROVIDER_RATE_LIMIT", "PROVIDER_TIMEOUT"];

  for (let attempt = 1; ; attempt += 1) {
    if (config.signal?.aborted) throw new AbortError();
    try {
      return await fn();
    } catch (error) {
      if (attempt >= maxAttempts || !shouldRetry(error, retryOnCodes)) {
        throw error;
      }

      let delay = Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1));
      delay = delay * (0.8 + Math.random() * 0.4);
      if (
        error instanceof RateLimitError
        && error.retryAfter !== undefined
        && Number.isFinite(error.retryAfter)
        && error.retryAfter >= 0
      ) {
        delay = Math.max(delay, error.retryAfter * 1_000);
      }
      await new Promise<void>((resolve, reject) => {
        const signal = config.signal;
        const abort = () => { clearTimeout(timer); signal?.removeEventListener("abort", abort); reject(new AbortError()); };
        const timer = setTimeout(() => { signal?.removeEventListener("abort", abort); resolve(); }, delay);
        signal?.addEventListener("abort", abort, { once: true });
        if (signal?.aborted) abort();
      });
    }
  }
}
