import { Adapter, WhereClause } from "@superfunctions/db";
import { NonProductionBackendError } from "../core/errors.js";
import { secureRandomUUID } from "../utils/random.js";
import { cosineSimilarity, Document, Embeddings, matchesRetrievalFilter, RetrievalOptions, VectorStore } from "./base.js";

export interface DocumentRecord {
  id: string;
  content: string;
  embedding: number[];
  metadata: Record<string, unknown>;
  namespace: string;
  createdAt: number;
  score?: number;
}

export interface DbVectorStoreOptions {
  /** Row-level namespace passed to the backing database adapter. Defaults to `namespace`. */
  adapterNamespace?: string;
  /** Logical namespace stored on and used to filter document records. */
  namespace?: string;
  mode?: "reference" | "production";
  pageSize?: number;
  maxScan?: number;
  indexedSearch?: (payload: {
    query: string;
    k: number;
    filter?: Record<string, unknown>;
    namespace: string;
    queryEmbedding: number[];
  }) => Promise<DocumentRecord[]>;
}

/**
 * Reference DB vector store. This fallback is intentionally non-production unless an indexed search callback is supplied.
 */
export class DbVectorStore extends VectorStore {
  readonly backendType: "reference" | "production";
  private readonly tableName = "langfn_documents";
  private readonly adapterNamespace: string;
  private readonly namespace: string;
  private readonly pageSize: number;
  private readonly maxScan: number;
  private readonly indexedSearch?: DbVectorStoreOptions["indexedSearch"];

  constructor(
    private readonly db: Adapter,
    private readonly embeddings: Embeddings,
    options: DbVectorStoreOptions = {}
  ) {
    super();
    this.namespace = options.namespace ?? "default";
    this.adapterNamespace = options.adapterNamespace ?? this.namespace;
    this.backendType = options.mode ?? "reference";
    this.pageSize = Math.max(1, options.pageSize ?? 64);
    this.maxScan = Math.max(this.pageSize, options.maxScan ?? 512);
    this.indexedSearch = options.indexedSearch;
  }

  async addDocuments(documents: Document[]): Promise<void> {
    const texts = documents.map((document) => document.content);
    const vectors = await this.embeddings.embedDocuments(texts);
    const records: DocumentRecord[] = documents.map((document, index) => ({
      id: `doc_${secureRandomUUID()}`,
      content: document.content,
      embedding: vectors[index]!,
      metadata: { ...document.metadata },
      namespace: this.namespace,
      createdAt: Date.now()
    }));
    await this.db.createMany({
      model: this.tableName,
      data: records,
      namespace: this.adapterNamespace
    });
  }

  async search(query: string, options: RetrievalOptions = {}): Promise<Document[]> {
    const k = options.k ?? 4;
    const queryEmbedding = await this.embeddings.embedQuery(query);
    const records = this.indexedSearch
      ? await this.indexedSearch({
          query,
          k,
          filter: options.filter,
          namespace: this.namespace,
          queryEmbedding
        })
      : await this.referenceSearch(queryEmbedding, options, k);

    return records
      .slice(0, k)
      .map((record) => ({
        content: record.content,
        metadata: { ...record.metadata },
        score: record.score
      }));
  }

  private async referenceSearch(
    queryEmbedding: number[],
    options: RetrievalOptions,
    k: number
  ): Promise<DocumentRecord[]> {
    if (this.backendType === "production") {
      throw new NonProductionBackendError("Production retrieval requires adapter-native indexed search or memoryfn", {
        metadata: { backend: "db-vector-store" }
      });
    }

    const where: WhereClause[] = [{ field: "namespace", operator: "eq", value: this.namespace }];
    const scored: DocumentRecord[] = [];
    let offset = 0;

    while (offset < this.maxScan) {
      const limit = Math.min(this.pageSize, this.maxScan - offset);
      const records = await this.db.findMany<DocumentRecord>({
        model: this.tableName,
        where,
        limit,
        offset,
        namespace: this.adapterNamespace
      });
      if (!records.length) {
        break;
      }

      records.forEach((record, index) => {
        if (!matchesRetrievalFilter(record.metadata ?? {}, options.filter)) {
          return;
        }
        scored.push({
          ...record,
          score: cosineSimilarity(queryEmbedding, record.embedding),
          createdAt: record.createdAt ?? offset + index
        });
      });

      offset += records.length;
      if (records.length < limit) {
        break;
      }
    }

    return scored
      .sort((left, right) => (right.score ?? 0) - (left.score ?? 0) || left.createdAt - right.createdAt)
      .slice(0, Math.max(k, 1));
  }
}
import { secureRandomUUID } from "../utils/random.js";
import { redact } from "./redaction.js";
import { ObservabilityExporter, type ObservabilityExporterConfig } from "./exporter.js";
import type { SpanRecord, TraceStorage } from "./storage.js";

export interface TraceSpanOptions {
  traceId?: string;
  parentSpanId?: string;
  metadata?: Record<string, unknown>;
}

export interface TracerConfig extends ObservabilityExporterConfig {
  storage?: TraceStorage;
  redactionKeys?: string[];
}

class TraceSpanHandle {
  readonly traceId: string;
  readonly spanId: string;
  private readonly startedAt = Date.now();
  private finished = false;

  constructor(
    private readonly tracer: Tracer,
    private readonly name: string,
    traceId: string,
    private readonly parentSpanId: string | undefined,
    private readonly metadata: Record<string, unknown>
  ) {
    this.traceId = traceId;
    this.spanId = randomId();
  }

  async start(): Promise<void> {
    await this.tracer.emit(this.name, {
      phase: "start",
      traceId: this.traceId,
      spanId: this.spanId,
      parentSpanId: this.parentSpanId,
      metadata: this.metadata
    });
  }

  async fail(error: unknown): Promise<void> {
    await this.finish("error", error);
  }

  async [Symbol.asyncDispose](): Promise<void> {
    await this.finish("ok");
  }

  private async finish(status: "ok" | "error", error?: unknown): Promise<void> {
    if (this.finished) {
      return;
    }
    this.finished = true;

    const spanRecord: SpanRecord = {
      traceId: this.traceId,
      spanId: this.spanId,
      parentSpanId: this.parentSpanId,
      name: this.name,
      metadata: this.metadata,
      status,
      startedAt: this.startedAt,
      endedAt: Date.now(),
      error: error ? serializeError(error) : undefined
    };
    await this.tracer.storage?.saveSpan(spanRecord);
    await this.tracer.emit(this.name, {
      phase: status === "ok" ? "end" : "error",
      traceId: this.traceId,
      spanId: this.spanId,
      parentSpanId: this.parentSpanId,
      metadata: this.metadata,
      error: error ? serializeError(error) : undefined
    });
  }
}

export class Tracer {
  readonly storage?: TraceStorage;
  private readonly exporter: ObservabilityExporter;
  private readonly redactionKeys: string[];

  constructor(config: TracerConfig = {}) {
    this.storage = config.storage;
    this.exporter = new ObservabilityExporter(config);
    this.redactionKeys = [...(config.redactionKeys ?? [])];
  }

  createTraceId(): string {
    return randomId();
  }

  sanitize<T>(payload: T): T {
    return redact(payload, { keys: this.redactionKeys });
  }

  async emit(name: string, payload: Record<string, unknown>): Promise<Record<string, unknown>> {
    const safePayload = this.sanitize(payload) as Record<string, unknown>;
    await this.exporter.emit(name, safePayload);
    return safePayload;
  }

  async span(name: string, options: TraceSpanOptions = {}): Promise<TraceSpanHandle> {
    const handle = new TraceSpanHandle(
      this,
      name,
      options.traceId ?? this.createTraceId(),
      options.parentSpanId,
      (this.sanitize(options.metadata ?? {}) as Record<string, unknown>)
    );
    await handle.start();
    return handle;
  }

  async trace<T>(
    name: string,
    metadata: Record<string, unknown>,
