export class RateLimitError extends LangFnError {
  readonly retryAfter?: number;

  constructor(
    message = "Provider rate limit exceeded",
    options: Omit<ConstructorParameters<typeof LangFnError>[1], "code" | "metadata"> & {
      retryAfter?: number;
