    await expect(storage.searchVectors({
      tenantId: 'tenant-a',
      embedding: [1, 0],
      containerTags: ['scope:a'],
      filters: { kind: 'note' },
      topK: 1,
    })).resolves.toEqual([expect.objectContaining({ content: 'visible' })]);
