  const scope = {tenantId:'t',containerTags:['w']};
  const fn = new MemoryFn({storage:{kind:'adapter',adapter:store}},store,
    {embed:async()=>[1,0],embedBatch:async(values:string[])=>values.map(()=>[1,0])});
