    // dependency on this package's RouterError class. Honor only explicit,
    // valid error status metadata; arbitrary exceptions remain generic 500s.
    const httpError = error as {
      isHttpError?: unknown;
      message?: unknown;
      code?: unknown;
      statusCode?: unknown;
    };
